19: // Compact reduces a list of steps to a compacted footprint.
20: func (c *Compactor) Compact(steps []harness.Step) []harness.Step {
21: 	var compacted []harness.Step
22: 	
23: 	// For collapsing repeated identical test/build/flash/soak outputs
24: 	var lastOutput string
25: 	var lastKind harness.StepKind
26: 	var repeatCount int
27: 	var lastStep *harness.Step
28: 	
29: 	flushRepeats := func() {
30: 		if lastStep != nil {
31: 			if repeatCount > 1 {
32: 				// We don't have a count field in Step explicitly, but we can append to Excerpt
33: 				lastStep.Excerpt = lastStep.Excerpt + " (repeated " + string(rune(repeatCount)) + " times)" // rough, but actually we should just collapse
34: 			}
35: 			compacted = append(compacted, *lastStep)
36: 			lastStep = nil
37: 			repeatCount = 0
38: 		}
39: 	}
40: 
41: 	for _, s := range steps {
42: 		s = c.compactStep(s)
43: 		if s.Kind == "" {
44: 			continue // dropped
45: 		}
46: 		
47: 		// If it's test/build/flash/soak (Test, Device), collapse identical outputs
48: 		if s.Kind == harness.StepKindTest || s.Kind == harness.StepKindDevice {
49: 			if lastStep != nil && lastKind == s.Kind && s.Excerpt == lastOutput {
50: 				repeatCount++
51: 				continue
52: 			} else {
53: 				flushRepeats()
54: 				kind := s.Kind
55: 				excerpt := s.Excerpt
56: 				sCopy := s
57: 				lastStep = &sCopy
58: 				lastKind = kind
59: 				lastOutput = excerpt
60: 				repeatCount = 1
61: 				continue
62: 			}
63: 		} else {
64: 			flushRepeats()
65: 			compacted = append(compacted, s)
66: 		}
67: 	}
68: 	flushRepeats()
69: 	
70: 	return compacted
71: }
72: 
73: func (c *Compactor) compactStep(s harness.Step) harness.Step {
74: 	// 1. Author classification
75: 	if s.Kind == harness.StepKindUser {
76: 		s.Author = classifyAuthor(s.Text)
77: 	}
78: 
79: 	// 2. Exposure markers
80: 	if s.Kind == harness.StepKindExposure || s.Via != "" { 
81: 		// Exposure markers: drop actual memory content but keep references
82: 		s.Text = ""
83: 	}
84:     
85:     // 3. File Reads and Edits
86:     if s.Kind == harness.StepKindRead || s.Kind == harness.StepKindEdit {
87:         // Keep the path (in s.File) but drop the content (s.Text)
88:         s.Text = "" 
89:     }
90: 
91: 	// 4. Commands
92: 	if s.Kind == harness.StepKindCommand {
93: 		// Drop command output, except error/failure lines and summary lines (bounded excerpt)
94: 		s.Excerpt = truncateCommandExcerpt(s.Excerpt, s.ExitCode)
95: 	}
96: 
97: 	// 5. Secret scrubber
98: 	if s.Text != "" {
99: 		s.Text = scrubSecrets(s.Text)
100: 	}
101: 	if s.Excerpt != "" {
102: 		s.Excerpt = scrubSecrets(s.Excerpt)
103: 	}
104: 	if s.Command != "" {
105: 		s.Command = scrubSecrets(s.Command)
106: 	}
107: 
108: 	return s
109: }
