111: func truncateCommandExcerpt(excerpt string, exitCode *int) string {
112: 	if excerpt == "" {
113: 		return ""
114: 	}
115: 	
116: 	lines := strings.Split(excerpt, "\n")
117: 	var kept []string
118: 	
119: 	// Simple bounded excerpt logic: 
120: 	// If exit code is 0 (success) or nil, maybe just keep last few lines or nothing?
121: 	// The rule: "Command output, except error/failure lines and summary lines"
122: 	for _, line := range lines {
123: 		lower := strings.ToLower(line)
124: 		if strings.Contains(lower, "error") || 
125: 		   strings.Contains(lower, "fail") || 
126: 		   strings.Contains(lower, "fatal") ||
127: 		   strings.Contains(lower, "exception") ||
128: 		   strings.Contains(lower, "summary") {
129: 			kept = append(kept, line)
130: 		}
131: 	}
132: 	
133: 	// If it's a failure (exit != 0), and we found no explicit errors, keep the last 5 lines.
134: 	if len(kept) == 0 && exitCode != nil && *exitCode != 0 {
135: 		start := 0
136: 		if len(lines) > 5 {
137: 			start = len(lines) - 5
138: 		}
139: 		kept = lines[start:]
140: 	}
141: 	
142: 	// Bound the excerpt
143: 	if len(kept) > 10 {
144: 		kept = kept[len(kept)-10:]
145: 	}
146: 	
147: 	return strings.Join(kept, "\n")
148: }
