150: func classifyAuthor(text string) string {
151: 	lower := strings.ToLower(text)
152: 	if strings.Contains(lower, "agentapi") || 
153: 	   strings.Contains(lower, "bug-fixer") || 
154: 	   strings.Contains(lower, "desktop scheduled task") ||
155: 	   strings.Contains(lower, "-p run") || 
156: 	   strings.Contains(lower, "system generated") ||
157: 	   strings.HasPrefix(lower, "<system_message>") {
158: 		return "automation"
159: 	}
160: 	return "human"
161: }
