163: func scrubSecrets(text string) string {
164: 	// Secret scrubber (pattern + entropy) replacing matches with «secret:type»
165: 	
166: 	// Mock AWS key
167: 	awsKeyRegex := regexp.MustCompile(`(?i)(?:AKIA|A3T|AGPA|AIDA|AROA|AIPA|ANPA|ANVA|ASIA)[A-Z0-9]{16}`)
168: 	text = awsKeyRegex.ReplaceAllString(text, "«secret:aws»")
169: 	
170: 	// UUID
171: 	uuidRegex := regexp.MustCompile(`(?i)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}`)
172: 	text = uuidRegex.ReplaceAllString(text, "«secret:uuid»")
173: 
174: 	// High entropy base64-like strings (tokens)
175: 	// Just a simple heuristic for tests
176: 	tokenRegex := regexp.MustCompile(`(?i)(?:bearer|token)\s+([a-zA-Z0-9\-\.]{20,})`)
177: 	text = tokenRegex.ReplaceAllStringFunc(text, func(m string) string {
178: 		parts := strings.SplitN(m, " ", 2)
179: 		if len(parts) == 2 {
180: 			return parts[0] + " «secret:token»"
181: 		}
182: 		return "«secret:token»"
183: 	})
184: 	
185: 	// Simple hex key entropy
186: 	hexRegex := regexp.MustCompile(`[0-9a-fA-F]{32,}`)
187: 	text = hexRegex.ReplaceAllString(text, "«secret:hex»")
188:     
189:     return text
190: }
